"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[67795],{25239:e=>{e.exports=JSON.parse('{"month":"2026-08","entries":[{"id":"2026-08-27-viber-get-delete-template-endpoints","date":"2026-08-27","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Get and Delete Viber template endpoints","excerpt":"You can now retrieve and delete Viber message templates via API, in addition to creating them.","hasArticle":true},{"id":"2026-08-26-converse-2-0-api-documentation","date":"2026-08-26","products":["Converse"],"product":"Converse","channel":"","changeType":"Added","title":"Converse 2.0 API documentation, now at its own /converse section","excerpt":"Converse now has full API documentation, and its own top-level section on the developer portal \u2014 no longer nested under Connect.","hasArticle":true},{"id":"2026-08-26-streaming-migration-messaging-updated","date":"2026-08-26","products":["Actions & Events"],"product":"Actions & Events","channel":"","changeType":"Changed","title":"Event Streaming migration guidance updated for general availability","excerpt":"The Event Streaming migration guide and overview no longer describe moving off the legacy Streaming API (SAPI) as optional. Existing customers are automatically migrated to the Pulsar-based Event Streaming service on a rolling schedule, with advance notice sent ahead of each migration.","hasArticle":true},{"id":"2026-08-24-override-turn-relay-region","date":"2026-08-24","products":["JaaS"],"product":"JaaS","channel":"","changeType":"Added","title":"Override the TURN relay region","excerpt":"You can now pin a meeting\'s TURN relay to a specific region using the experimental iceServers option on the JitsiMeetExternalAPI constructor. This is separate from pinning the meeting to a regional data center: that controls where the media bridge (JVB) lives, while iceServers controls which TURN relay a participant\'s\u2026","hasArticle":true},{"id":"2026-08-19-outboundcontent-timing-corrected","date":"2026-08-19","products":["Connect","APIs"],"product":"Connect","channel":"","changeType":"Fixed","title":"outboundContent timing corrected on WhatsApp delivery receipts","excerpt":"The Delivery receipts for Outbound Messaging Apps(/connect/docs/delivery-receipts-for-outbound-chatapps) guide previously stated that the outboundContent object is attached to the receipt confirming delivery to the recipient (deliveredtorecipient). That was inaccurate.","hasArticle":true},{"id":"2026-08-13-viber-template-send-examples","date":"2026-08-13","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Viber template send examples in the Send message reference","excerpt":"The Send message API reference now includes worked request examples for sending Viber template messages, covering both template categories: transactional templates and OTP templates.","hasArticle":true},{"id":"2026-08-11-rcs-rich-card-media-height-optional","date":"2026-08-11","products":["Connect","APIs"],"product":"Connect","channel":"RCS","changeType":"Fixed","title":"RCS rich card media height documented as optional","excerpt":"The media.height field on RCS rich cards was documented as if a value were always required. It is now clarified as optional, defaulting to SHORT when omitted.","hasArticle":true},{"id":"2026-08-10-event-field-json-types-not-fixed","date":"2026-08-10","products":["Actions & Events"],"product":"Actions & Events","channel":"","changeType":"Fixed","title":"Event Streaming field reference corrected: JSON types are not fixed per field","excerpt":"The Event Streaming field reference previously said boolean values in events \\"are represented as strings... rather than native JSON booleans\\" \u2014 a claim its own example immediately contradicted by showing both a quoted and an unquoted boolean value in the same payload. The section has been corrected and expanded to desc\u2026","hasArticle":true},{"id":"2026-08-10-interaction-event-timestamp-corrected","date":"2026-08-10","products":["Actions & Events"],"product":"Actions & Events","channel":"","changeType":"Fixed","title":"Event Streaming timestamp field corrected: use interactionEventTS for event time","excerpt":"The Event Streaming field and event reference docs previously told integrators to use eventTS to calculate durations between lifecycle events \u2014 queue time, ring time, talk time, and wrap-up time. That was incorrect: eventTS is the time the interaction was first offered (queue entry), and it carries the identical value\u2026","hasArticle":true},{"id":"2026-08-10-prejoin-config-enabled","date":"2026-08-10","products":["JaaS"],"product":"JaaS","channel":"","changeType":"Changed","title":"Prejoin page config option renamed","excerpt":"The Prejoin page guide(/jaas/docs/jaas-prefs-prejoin) now uses prejoinConfig.enabled in place of the retired prejoinPageEnabled option. The IFrame API checks each configOverwrite key against an allow-list and silently drops keys it doesn\'t recognize, so apps still setting prejoinPageEnabled: false were left with the pr\u2026","hasArticle":true},{"id":"2026-08-07-viber-message-templates","date":"2026-08-07","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Viber message templates","excerpt":"You can now create and manage Viber message templates \u2014 pre-approved message formats for transactional messages and OTPs, with dynamic {{parameter}} placeholders substituted at send time. Creating templates requires an admin role on the account.","hasArticle":true},{"id":"2026-08-06-alerting-rt-scope-clarified","date":"2026-08-06","products":["Analytics"],"product":"Analytics","channel":"","changeType":"Changed","title":"alerting.rt scope clarified","excerpt":"The Real-Time Statistics documentation now spells out exactly what the alerting.rt metric counts and what it excludes, so it is interpreted consistently. This is a documentation clarification \u2014 there is no change to the metric\'s behaviour.","hasArticle":true},{"id":"2026-08-05-rcs-attribution-corrected","date":"2026-08-05","products":["Connect"],"product":"Connect","channel":"RCS","changeType":"Fixed","title":"RCS attribution corrected","excerpt":"The RCS guide previously described Rich Communication Services as \\"a protocol developed by Google.\\" That was inaccurate, and it is now corrected.","hasArticle":true},{"id":"2026-08-04-bridge-adapter-endpoint-for-sapi-migration","date":"2026-08-04","products":["Actions & Events"],"product":"Actions & Events","channel":"Streaming","changeType":"Added","title":"Bridge adapter endpoint for SAPI migration","excerpt":"The Streaming API migration guide now documents a backwards-compatible adapter (Bridge) endpoint \u2014 a second migration path for existing Streaming API integrations that cannot move to the Pulsar API directly.","hasArticle":true},{"id":"2026-08-04-templateid-in-direct-send-delivery-receipts","date":"2026-08-04","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"templateId in Direct Send delivery receipts","excerpt":"WhatsApp delivery receipts now include a templateId field for messages sent via the WhatsApp Direct Send API, so you can correlate a receipt back to the exact template that was delivered.","hasArticle":true},{"id":"2026-08-03-line-channel-documentation","date":"2026-08-03","products":["Connect"],"product":"Connect","channel":"LINE","changeType":"Added","title":"LINE channel documentation","excerpt":"The full LINE channel documentation is now published. LINE is the most popular chat app in Japan, Thailand, and Taiwan, and it reaches users through the same 8x8 Messaging Apps API and webhook envelope you already use for SMS, WhatsApp, Viber, and RCS.","hasArticle":true}]}')}}]);